using System.Collections.ObjectModel;
using Avalonia.Threading;
using Daqifi.Desktop.Common.Loggers;

namespace Daqifi.Desktop.Device.Firmware;

/// <summary>
/// Default <see cref="IBootloaderWatcher"/> implementation. Runs continuous HID-bootloader discovery and,
/// for every bootloader it finds, opens an exclusive per-device hold (its own transport, keyed by device
/// path) with a keep-alive read so Windows USB selective-suspend can't wedge it before flashing
/// (daqifi-nyquist-firmware#568). All mutating operations are serialized through <see cref="_gate"/>; the
/// bound <see cref="Bootloaders"/> collection is mutated on the UI thread.
/// </summary>
// @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher
public sealed class BootloaderWatcher : IBootloaderWatcher, IDisposable
{
    #region Private Fields
    private readonly IBootloaderDiscovery _discovery;
    private readonly Func<string, string?, IBootloaderHoldService> _holdFactory;
    private readonly IAppLogger _logger;
    private readonly SemaphoreSlim _gate = new(1, 1);

    // Source of truth, keyed by device path. Mirrored into Bootloaders for the UI.
    private readonly Dictionary<string, IBootloaderHoldService> _holds = new(StringComparer.Ordinal);

    private bool _started;
    private bool _disposed;

    // The devices currently being flashed (each one's hold is released so the flasher can open it);
    // new grabs for these paths are suppressed until their flash leases are disposed. Counted, so a
    // repeated PrepareFlashAsync for the same path still needs one disposal each.
    //
    // Upstream keeps a single nullable path here, which is exactly right for the one caller that
    // exists — FirmwareDialogViewModel, reachable only through a modal dialog opened from another
    // modal dialog, so two flashes cannot overlap today. But PrepareFlashAsync hands out an
    // independent lease per call and IsFlashInProgress now publishes "a write is in flight" to the
    // connection dialog's discovery guards, and with one shared slot the FIRST disposal of two
    // overlapping leases would clear that state and let discovery probe the bus into the second,
    // still-running write. Counting is a no-op on the reachable path and keeps the published state
    // honest if a second caller ever appears.
    private readonly Dictionary<string, int> _flashingPaths = new(StringComparer.Ordinal);

    // Total outstanding flash leases — a single-field mirror of the summed counts above, written under
    // _gate. IsFlashInProgress is polled by callers that hold no gate (the connection dialog's
    // Start*Discovery guards), so it has to read one field rather than walk a dictionary.
    private int _outstandingFlashes;

    // Set while an auto-update is in progress: discovery is paused and new grabs are suppressed, but
    // existing holds stay alive so other sitting bootloaders remain wedge-proof.
    private bool _grabSuppressed;
    #endregion

    #region Constructor
    /// <summary>Creates the watcher.</summary>
    /// <param name="discovery">Continuous HID-bootloader discovery source.</param>
    /// <param name="holdFactory">
    /// Creates a per-device hold (device path, friendly name) → hold service. Each hold owns its own
    /// exclusive HID transport so holding/flashing one device never disturbs the others.
    /// </param>
    /// <param name="logger">Application logger for diagnostics.</param>
    public BootloaderWatcher(
        IBootloaderDiscovery discovery,
        Func<string, string?, IBootloaderHoldService> holdFactory,
        IAppLogger logger)
    {
        _discovery = discovery ?? throw new ArgumentNullException(nameof(discovery));
        _holdFactory = holdFactory ?? throw new ArgumentNullException(nameof(holdFactory));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        Bootloaders = new ReadOnlyObservableCollection<HeldBootloader>(_bootloaders);
    }
    #endregion

    #region IBootloaderWatcher
    // Internal mutable backing; the public surface is a read-only view so external code (the bound
    // dialog) can observe the list but cannot mutate the watcher's state.
    private readonly ObservableCollection<HeldBootloader> _bootloaders = [];

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.Bootloaders
    public ReadOnlyObservableCollection<HeldBootloader> Bootloaders { get; }

    /// <inheritdoc />
    public event EventHandler<BootloaderHoldDroppedEventArgs>? HoldDropped;

    /// <inheritdoc />
    public event EventHandler? FlashInProgressChanged;

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.IsFlashInProgress
    // Volatile read: _outstandingFlashes is written under _gate, but this is polled from callers that
    // hold no gate (the connection dialog's Start*Discovery guards), so the read must not be
    // hoisted/cached.
    public bool IsFlashInProgress => Volatile.Read(ref _outstandingFlashes) > 0;

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.Start
    public void Start()
    {
        if (_disposed || _started)
        {
            return;
        }

        _started = true;
        _discovery.BootloaderDiscovered += OnBootloaderDiscovered;
        _discovery.Start();
        _logger.Information("Bootloader watcher started; holding every detected HID bootloader app-wide.");
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.PrepareFlashAsync
    public async Task<IAsyncDisposable> PrepareFlashAsync(string devicePath)
    {
        ArgumentNullException.ThrowIfNull(devicePath);

        bool flashStarted;
        await _gate.WaitAsync().ConfigureAwait(false);
        try
        {
            // Pause discovery and mark this device as a flash target so it isn't re-grabbed while the
            // flasher owns it. Other holds are left untouched (they stay wedge-proof).
            _discovery.Stop();
            flashStarted = _outstandingFlashes == 0;
            _flashingPaths[devicePath] = _flashingPaths.GetValueOrDefault(devicePath) + 1;
            Volatile.Write(ref _outstandingFlashes, _outstandingFlashes + 1);

            try
            {
                if (_holds.TryGetValue(devicePath, out var hold))
                {
                    // Release ONLY the target so the flasher's transport can open it by path. Graceful release
                    // (no HoldDropped); the hold object is kept so the lease can re-grab the same device after.
                    await hold.ReleaseAsync().ConfigureAwait(false);
                    _logger.Information($"Released hold on {devicePath} for flashing; other bootloaders stay held.");
                }
            }
            catch
            {
                // The marker is raised before this await (a concurrent auto-update ending must not see a
                // gap), so a failure here has to roll it back by hand: no lease is returned when this
                // throws, so nothing would ever release it. A stranded marker does not just pause HID
                // discovery any more — the connection dialog keys its serial and WiFi discovery on
                // IsFlashInProgress too, so it would leave the whole bus unscanned for the life of the
                // process, for a flash that never started.
                ReleaseFlashSlot(devicePath);
                ResumeDiscoveryIfIdle();
                throw;
            }
        }
        finally
        {
            _gate.Release();
        }

        // Unreachable on the failure path above, which rethrows — so a flash that never started never
        // announces a rising edge, and no subscriber is left waiting for a falling one.

        if (flashStarted)
        {
            RaiseFlashInProgressChanged();
        }

        return new WatcherLease(() => ResumeAfterFlashAsync(devicePath));
    }

    /// <inheritdoc />
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.SuspendDiscoveryAsync
    public async Task<IAsyncDisposable> SuspendDiscoveryAsync()
    {
        await _gate.WaitAsync().ConfigureAwait(false);
        try
        {
            _discovery.Stop();
            _grabSuppressed = true;
            _logger.Information("Bootloader watcher discovery suspended for an auto-update; existing holds kept.");
        }
        finally
        {
            _gate.Release();
        }

        return new WatcherLease(ResumeDiscoveryAsync);
    }
    #endregion

    #region Resume (lease disposal)
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.ResumeAfterFlashAsync
    private async Task ResumeAfterFlashAsync(string devicePath)
    {
        var flashEnded = false;
        await _gate.WaitAsync().ConfigureAwait(false);
        try
        {
            // Re-grab only when this lease is the last one outstanding for THIS path: reopening the
            // handle while another write to the same device is still running would fight it. Read
            // before the release below, which is deliberately deferred past the await.
            var lastLeaseForThisPath = _flashingPaths.GetValueOrDefault(devicePath) <= 1;
            try
            {
                if (lastLeaseForThisPath && _holds.TryGetValue(devicePath, out var hold))
                {
                    // Re-grab the exact device by path. A failed/cancelled flash leaves it a bootloader →
                    // re-held. A successful flash left it in application mode → the open fails and we drop it.
                    await hold.BeginHoldAsync().ConfigureAwait(false);
                    if (!hold.IsHolding)
                    {
                        RemoveHold(devicePath, hold);
                        _logger.Information($"{devicePath} is no longer a bootloader after flashing; dropped from the held list.");
                    }
                }
            }
            finally
            {
                // Drop the marker only once the handoff is complete. IsFlashInProgress is polled with no
                // gate held (the connection dialog's discovery guards), so clearing it before awaiting the
                // re-grab would advertise "flash over" while the HID handle is still being reopened and let
                // the dialog resume bus probing into it. The finally is what keeps an unexpected re-grab
                // failure from stranding the marker set, which would pause that discovery for good.
                flashEnded = ReleaseFlashSlot(devicePath);

                ResumeDiscoveryIfIdle();
            }
        }
        finally
        {
            _gate.Release();

            if (flashEnded)
            {
                RaiseFlashInProgressChanged();
            }
        }
    }

    /// <summary>
    /// Drops one outstanding flash lease for <paramref name="devicePath"/>, returning true when it was
    /// the last outstanding lease of any kind — i.e. when <see cref="IsFlashInProgress"/> just went
    /// false and the falling edge is owed. Must be called under <see cref="_gate"/>.
    /// </summary>
    private bool ReleaseFlashSlot(string devicePath)
    {
        if (!_flashingPaths.TryGetValue(devicePath, out var outstanding))
        {
            // Nothing to release. Reachable only if a lease were disposed twice, which WatcherLease
            // already prevents; returning false keeps a spurious falling edge out of the event.
            return false;
        }

        if (outstanding <= 1)
        {
            _flashingPaths.Remove(devicePath);
        }
        else
        {
            _flashingPaths[devicePath] = outstanding - 1;
        }

        var remaining = _outstandingFlashes - 1;
        Volatile.Write(ref _outstandingFlashes, remaining);
        return remaining == 0;
    }

    /// <summary>
    /// Raises <see cref="FlashInProgressChanged"/>. Always called with <see cref="_gate"/> released:
    /// subscribers react by marshalling onto the UI thread, and doing that under the gate could
    /// lock-invert with a UI-thread gate acquisition (the same reason <see cref="HoldDropped"/> is raised
    /// outside it). Guarded so a faulting subscriber cannot propagate into the flash lease's disposal and
    /// mask the flash's own outcome.
    /// </summary>
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.RaiseFlashInProgressChanged
    private void RaiseFlashInProgressChanged()
    {
        var handlers = FlashInProgressChanged;
        if (handlers == null)
        {
            return;
        }

        // Invoke each subscriber independently rather than wrapping the multicast delegate in one
        // try/catch: a single throwing subscriber would otherwise swallow the edge for every handler
        // registered after it, and for a connection dialog the falling edge is its only resume trigger.
        foreach (var handler in handlers.GetInvocationList().Cast<EventHandler>())
        {
            try
            {
                handler(this, EventArgs.Empty);
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "A FlashInProgressChanged subscriber threw while the flash state changed.");
            }
        }
    }

    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.ResumeDiscoveryAsync
    private async Task ResumeDiscoveryAsync()
    {
        await _gate.WaitAsync().ConfigureAwait(false);
        try
        {
            _grabSuppressed = false;
            ResumeDiscoveryIfIdle();
            _logger.Information("Bootloader watcher discovery resumed after auto-update.");
        }
        finally
        {
            _gate.Release();
        }
    }

    /// <summary>
    /// Restarts discovery only when no operation still needs it paused. Manual flashes
    /// (<see cref="_outstandingFlashes"/>) and an auto-update (<see cref="_grabSuppressed"/>) can
    /// overlap on a multi-device bench; whichever lease disposes first must NOT resume discovery while
    /// another is still flashing — a live finder cycle could re-open an in-flight device during the
    /// flasher's reconnect window. Must be called under <see cref="_gate"/>.
    /// </summary>
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.ResumeDiscoveryIfIdle
    private void ResumeDiscoveryIfIdle()
    {
        // Only (re)start discovery if the watcher was ever started. In test/tooling mode
        // App.Initialize skips Start() (#18), yet the firmware-flash and auto-update flows have no
        // test-mode gate of their own and still route here on lease disposal — without this guard
        // that would start HID discovery the gate exists to prevent, and half-initialized at that
        // (BootloaderDiscovered is subscribed only inside Start(), so devices would be probed every
        // pass but never held). Harmless upstream/in production, where Start() always runs first.
        if (_started && !_disposed && _outstandingFlashes == 0 && !_grabSuppressed)
        {
            _discovery.Start();
        }
    }
    #endregion

    #region Discovery / drop handling
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.OnBootloaderDiscovered
    private void OnBootloaderDiscovered(object? sender, BootloaderDiscoveredEventArgs e)
    {
        // The discovery loop is synchronous; grabbing the hold is async, so dispatch without blocking it.
        RunDetached(
            HandleDiscoveredAsync(e.DevicePath, e.DeviceName, e.LocationKey),
            "handling a discovered bootloader");
    }

    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.HandleDiscoveredAsync
    private async Task HandleDiscoveredAsync(string devicePath, string? deviceName, string? locationKey)
    {
        await _gate.WaitAsync().ConfigureAwait(false);
        IBootloaderHoldService? created = null;
        try
        {
            if (_disposed || _grabSuppressed || _flashingPaths.ContainsKey(devicePath) || _holds.ContainsKey(devicePath))
            {
                return;
            }

            created = _holdFactory(devicePath, deviceName);
            created.HoldDropped += OnHoldDropped;
            await created.BeginHoldAsync().ConfigureAwait(false);

            if (!created.IsHolding)
            {
                // Could not open it (already gone, or transitioned to application mode). Don't list it.
                created.HoldDropped -= OnHoldDropped;
                created.Dispose();
                created = null;
                return;
            }

            _holds[devicePath] = created;
            created = null; // ownership transferred to _holds BEFORE the UI marshal, so a marshal failure
                            // can never make the finally dispose a now-tracked hold (stale-entry bug).
            var displayName = ResolveDisplayName(deviceName, locationKey);
            InvokeOnUiThread(() =>
            {
                // Guard: a callback queued just before Dispose must not re-add a row after teardown.
                if (!_disposed)
                {
                    _bootloaders.Add(new HeldBootloader(devicePath, displayName, locationKey));
                }
            });
            _logger.Information($"Holding HID bootloader {devicePath} ({displayName}).");
        }
        catch (Exception ex)
        {
            _logger.Error(ex, $"Failed to hold discovered bootloader {devicePath}.");
        }
        finally
        {
            // If we created a hold but didn't transfer ownership, tear it down so we don't leak it.
            if (created != null)
            {
                created.HoldDropped -= OnHoldDropped;
                created.Dispose();
            }
            _gate.Release();
        }
    }

    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.OnHoldDropped
    private void OnHoldDropped(object? sender, EventArgs e)
    {
        if (sender is IBootloaderHoldService hold && hold.DevicePath != null)
        {
            RunDetached(HandleHoldDroppedAsync(hold.DevicePath, hold), "handling a dropped bootloader hold");
        }
    }

    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.HandleHoldDroppedAsync
    private async Task HandleHoldDroppedAsync(string devicePath, IBootloaderHoldService hold)
    {
        await _gate.WaitAsync().ConfigureAwait(false);
        try
        {
            // Only act if this is still the live hold for the path (ignore a late event from a replaced one).
            if (_holds.TryGetValue(devicePath, out var current) && ReferenceEquals(current, hold))
            {
                RemoveHold(devicePath, hold);
                _logger.Information($"Held bootloader {devicePath} dropped (device removed).");
            }
        }
        finally
        {
            _gate.Release();
        }

        HoldDropped?.Invoke(this, new BootloaderHoldDroppedEventArgs(devicePath));
    }

    /// <summary>Removes and disposes a hold and its UI row. Must be called under <see cref="_gate"/>.</summary>
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.RemoveHold
    private void RemoveHold(string devicePath, IBootloaderHoldService hold)
    {
        hold.HoldDropped -= OnHoldDropped;
        _holds.Remove(devicePath);
        hold.Dispose();
        InvokeOnUiThread(() =>
        {
            // Guard: a callback queued just before Dispose must not mutate the list after teardown.
            if (_disposed)
            {
                return;
            }

            var row = _bootloaders.FirstOrDefault(b => string.Equals(b.DevicePath, devicePath, StringComparison.Ordinal));
            if (row != null)
            {
                _bootloaders.Remove(row);
            }
        });
    }
    #endregion

    #region Helpers
    /// <summary>
    /// Picks the label shown for a held bootloader: the friendly device name when discovery could read
    /// one, else the USB physical location when that's available, else a generic fallback. Identical
    /// bootloaders share VID/PID and have no serial (see <see cref="HeldBootloader"/>), so without a
    /// name the location key is the most useful thing to show a user with more than one connected.
    /// </summary>
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.ResolveDisplayName
    private static string ResolveDisplayName(string? deviceName, string? locationKey)
    {
        if (!string.IsNullOrWhiteSpace(deviceName))
        {
            return deviceName!;
        }

        return string.IsNullOrWhiteSpace(locationKey)
            ? "DAQiFi Bootloader"
            : $"Bootloader on USB port {locationKey}";
    }

    /// <summary>
    /// Observes a fire-and-forget task's faults. The handlers carry their own try/catch for expected
    /// failures; this is a backstop so an unexpected fault outside that scope (e.g. the gate already
    /// disposed during shutdown) is logged rather than going unobserved.
    /// </summary>
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.RunDetached
    private void RunDetached(Task task, string context)
    {
        _ = task.ContinueWith(
            t => _logger.Error(t.Exception!, $"Unhandled exception while {context}."),
            CancellationToken.None,
            TaskContinuationOptions.OnlyOnFaulted,
            TaskScheduler.Default);
    }

    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.InvokeOnUiThread
    private static void InvokeOnUiThread(Action action)
    {
        // WPF Application.Current.Dispatcher → Avalonia Dispatcher.UIThread. In unit tests (no pumped
        // UI loop) CheckAccess() is true on the test thread, so the mutation runs inline as upstream did.
        // Use the NON-blocking Post (WPF BeginInvoke): these calls happen while _gate is held, and a
        // blocking Invoke could lock-invert with Dispose()'s synchronous _gate.Wait() (UI thread waits on
        // the gate while a gate-holder waits on the UI thread). Post queues the mutation in order without
        // blocking, so no inversion is possible.
        if (Dispatcher.UIThread.CheckAccess())
        {
            action();
            return;
        }

        // Non-throwing: during app/dispatcher shutdown Post can throw, and these calls run inside the
        // gate-protected handlers — a marshal failure must never propagate (it would strand watcher
        // state). If the dispatcher is gone the bound list simply won't update, which is fine at shutdown.
        try
        {
            Dispatcher.UIThread.Post(action);
        }
        catch (Exception)
        {
            // Dispatcher unavailable / shutting down — drop the UI update.
        }
    }
    #endregion

    #region IDisposable
    /// <summary>Stops discovery and releases every held bootloader.</summary>
    // @port: Daqifi.Desktop.Device.Firmware.BootloaderWatcher.Dispose
    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        _discovery.BootloaderDiscovered -= OnBootloaderDiscovered;
        _discovery.Stop();
        (_discovery as IDisposable)?.Dispose();

        // Bounded wait so a stuck gate-holder can't hang app shutdown. Whether or not the gate is
        // acquired we STILL dispose the holds (best-effort) — skipping that on timeout would leak their
        // exclusive HID handles. Snapshot the holds first so a racing in-flight handler can't trip the
        // enumeration; release the gate only if we actually took it.
        var gateAcquired = _gate.Wait(TimeSpan.FromSeconds(2));
        if (!gateAcquired)
        {
            _logger.Warning(
                "Timed out acquiring the gate during bootloader watcher dispose; disposing holds best-effort.");
        }

        try
        {
            foreach (var hold in _holds.Values.ToList())
            {
                hold.HoldDropped -= OnHoldDropped;
                hold.Dispose();
            }
            _holds.Clear();
            InvokeOnUiThread(_bootloaders.Clear);
        }
        finally
        {
            if (gateAcquired)
            {
                _gate.Release();
            }
            _gate.Dispose();
        }
    }
    #endregion

    #region Lease
    /// <summary>An <see cref="IAsyncDisposable"/> that runs a resume action exactly once on disposal.</summary>
    private sealed class WatcherLease : IAsyncDisposable
    {
        private Func<Task>? _onDispose;

        public WatcherLease(Func<Task> onDispose) => _onDispose = onDispose;

        public async ValueTask DisposeAsync()
        {
            var action = Interlocked.Exchange(ref _onDispose, null);
            if (action != null)
            {
                await action().ConfigureAwait(false);
            }
        }
    }
    #endregion
}
